title: Linked Channels
description: Connect Discord channels with your application for seamless communication.
---
import PublicClient from '/snippets/discord-social-sdk/callouts/public-client.mdx';
import SupportCallout from '/snippets/discord-social-sdk/callouts/support.mdx';
import LimitedAccessCallout from '/snippets/discord-social-sdk/callouts/limited-access.mdx';
